//! Cargo-driven `mfreadwrite.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is mfreadwrite-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("mfreadwrite-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/mfreadwrite/mf_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:c:mfuuid", "engine:oldnames", "import:mf", "import:mfplat", "import:ole32", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        "x86_64" => &["dll/win32/mfreadwrite/mf_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:c:mfuuid", "engine:oldnames", "import:mf", "import:mfplat", "import:ole32", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["dll/win32/mfreadwrite/mf_classes_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:c:mfuuid", "engine:oldnames", "import:mf", "import:mfplat", "import:ole32", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("mfreadwrite-rust")
        .spec2def("dll/win32/mfreadwrite/mfreadwrite.spec", "mfreadwrite.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/mf/mf.spec", "mf.dll", "mf")
        .import_lib("dll/win32/mfplat/mfplat.spec", "mfplat.dll", "mfplat")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/kernelbase/kernelbase.spec", "kernelbase.dll", "kernelbase")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
